{-| @Backend.Runtime.Host.Desktop — outcomes and window tokens for the
    platform desktop adapter. -}
module Pudu.Backend.Runtime.Host.Desktop (hostDesktopParts) where

import Data.Text (Text)
import Pudu.Backend.Toolchain.HostSources (desktopSourceMarker)

hostDesktopParts :: [(Text, [Text], [Text])]
hostDesktopParts =
  [ ("host_desktop", ["host_optional", "host_fail", "host_done", "memory_failure", "kernel_signed"],
      [ desktopSourceMarker
      , "#if defined(__APPLE__)"
      , "#include \"pudu_desktop.h\""
      , "typedef struct pudu_window {"
      , "  int64_t token;"
      , "  void *handle;"
      , "  struct pudu_window *next;"
      , "} pudu_window;"
      , "static pudu_window *pudu_windows = NULL;"
      , "PUDU_OPTIONAL static int64_t pudu_window_next = 1;"
      , "PUDU_OPTIONAL static void pudu_desktop_teardown(void) {"
      , "  while (pudu_windows != NULL) {"
      , "    pudu_window *window = pudu_windows;"
      , "    pudu_windows = window->next;"
      , "    (void)pudu_desktop_close(window->handle);"
      , "    free(window);"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static pudu_window **pudu_window_find(pudu_int token) {"
      , "  pudu_window **slot = &pudu_windows;"
      , "  while (*slot != NULL && (*slot)->token != pudu_kernel_signed(token.bits)) slot = &(*slot)->next;"
      , "  if (*slot == NULL) pudu_host_fail(\"desktop session is closed or unknown\");"
      , "  return slot;"
      , "}"
      , "PUDU_OPTIONAL static int pudu_desktop_problem(const char *operation, int status) {"
      , "  char message[128];"
      , "  const char *detail;"
      , "  if (status == 0) { pudu_host_done(0); return 0; }"
      , "  switch (status) {"
      , "    case -1: detail = \"received an invalid argument\"; break;"
      , "    case -2: detail = \"must run on the main display thread\"; break;"
      , "    case -3: detail = \"received malformed frame bytes\"; break;"
      , "    default: detail = \"failed in the platform adapter\"; break;"
      , "  }"
      , "  snprintf(message, sizeof message, \"desktop %s %s\", operation, detail);"
      , "  pudu_host_fail(message);"
      , "  return 0;"
      , "}"
      , "#endif"
      ])
  , ("host_desktop_open", ["host_desktop", "kernel_int"],
      [ "static pudu_int pudu_host_desktop_open(pudu_text title, pudu_int width, pudu_int height, int resizable) {"
      , "#if defined(__APPLE__)"
      , "  int64_t width_value = pudu_kernel_signed(width.bits);"
      , "  int64_t height_value = pudu_kernel_signed(height.bits);"
      , "  if (title.length == 0) pudu_host_fail(\"desktop title is empty\");"
      , "  else if (width_value <= 0 || height_value <= 0) pudu_host_fail(\"desktop dimensions must be positive\");"
      , "  else if (width_value > INT32_MAX || height_value > INT32_MAX) pudu_host_fail(\"desktop dimensions exceed the platform limit\");"
      , "  else {"
      , "    static int cleanup_installed = 0;"
      , "    if (!cleanup_installed) {"
      , "      if (atexit(pudu_desktop_teardown) != 0) pudu_memory_failure();"
      , "      cleanup_installed = 1;"
      , "    }"
      , "    if (pudu_window_next == INT64_MAX) pudu_memory_failure();"
      , "    pudu_window *window = malloc(sizeof *window);"
      , "    if (window == NULL) pudu_memory_failure();"
      , "    void *handle = pudu_desktop_open(title.bytes, title.length, (int32_t)width_value, (int32_t)height_value, resizable);"
      , "    if (handle != NULL) {"
      , "      *window = (pudu_window){pudu_window_next++, handle, pudu_windows};"
      , "      pudu_windows = window;"
      , "      pudu_host_done(0);"
      , "      return pudu_kernel_int(window->token);"
      , "    }"
      , "    free(window);"
      , "    pudu_host_fail(\"desktop window could not open on the main display thread\");"
      , "  }"
      , "  return (pudu_int){0};"
      , "#else"
      , "  (void)title; (void)width; (void)height; (void)resizable;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return (pudu_int){0};"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_close", ["host_desktop"],
      [ "static int pudu_host_desktop_close(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  pudu_window *closed = *window;"
      , "  int status = pudu_desktop_close(closed->handle);"
      , "  if (status == 0) { *window = closed->next; free(closed); }"
      , "  return pudu_desktop_problem(\"close\", status);"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_present", ["host_desktop"],
      [ "static int pudu_host_desktop_present(pudu_int token, pudu_int width, pudu_int height, pudu_box * rgba) {"
      , "#if defined(__APPLE__)"
      , "  int64_t width_value = pudu_kernel_signed(width.bits);"
      , "  int64_t height_value = pudu_kernel_signed(height.bits);"
      , "  pudu_text frame = rgba->fields[0].text;"
      , "  if (width_value <= 0 || height_value <= 0) {"
      , "    pudu_host_fail(\"desktop dimensions must be positive\"); return 0;"
      , "  }"
      , "  if (frame.length % 4 != 0 || frame.length / 4 % (uint64_t)width_value != 0 ||"
      , "      frame.length / 4 / (uint64_t)width_value != (uint64_t)height_value) {"
      , "    pudu_host_fail(\"desktop frame does not match its dimensions\"); return 0;"
      , "  }"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  return pudu_desktop_problem(\"present\", pudu_desktop_present((*window)->handle,"
      , "    (int32_t)width_value, (int32_t)height_value, frame.bytes, frame.length));"
      , "#else"
      , "  (void)token; (void)width; (void)height; (void)rgba;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_pump", ["host_desktop", "host_time", "host_signal_requested"],
      [ "static int pudu_host_desktop_pump(pudu_int token, pudu_int milliseconds) {"
      , "#if defined(__APPLE__)"
      , "  int64_t milliseconds_value = pudu_kernel_signed(milliseconds.bits);"
      , "  if (milliseconds_value < 0) { pudu_host_fail(\"desktop pump duration must not be negative\"); return 0; }"
      , "  if (milliseconds_value > INT32_MAX) { pudu_host_fail(\"desktop pump duration exceeds the platform limit\"); return 0; }"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  uint64_t deadline = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) + (uint64_t)milliseconds_value * UINT64_C(1000000);"
      , "  for (;;) {"
      , "    uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);"
      , "    uint64_t remaining = now < deadline ? (deadline - now) / UINT64_C(1000000) : 0;"
      , "    int status = pudu_desktop_pump((*window)->handle, remaining > 16 ? 16 : (int32_t)remaining);"
      , "    if (status == 1) { pudu_host_done(0); return 1; }"
      , "    if (status != 0) return pudu_desktop_problem(\"pump\", status);"
      , "    if (remaining <= 16 || pudu_host_signal_requested()) { pudu_host_done(0); return 0; }"
      , "  }"
      , "#else"
      , "  (void)token; (void)milliseconds;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_configure", ["host_desktop"],
      [ "static int pudu_host_desktop_configure(pudu_int token, pudu_int density, pudu_int min_width, pudu_int min_height, pudu_int max_width, pudu_int max_height, pudu_int aspect_width, pudu_int aspect_height, int fullscreen) {"
      , "  /* Settings are refused on every platform before the platform is consulted. */"
      , "  int64_t density_value = pudu_kernel_signed(density.bits);"
      , "  int64_t min_width_value = pudu_kernel_signed(min_width.bits);"
      , "  int64_t min_height_value = pudu_kernel_signed(min_height.bits);"
      , "  int64_t max_width_value = pudu_kernel_signed(max_width.bits);"
      , "  int64_t max_height_value = pudu_kernel_signed(max_height.bits);"
      , "  int64_t aspect_width_value = pudu_kernel_signed(aspect_width.bits);"
      , "  int64_t aspect_height_value = pudu_kernel_signed(aspect_height.bits);"
      , "  const int64_t limits[] = {min_width_value, min_height_value, max_width_value, max_height_value};"
      , "  const char *problem = NULL;"
      , "  if (density_value < 250 || density_value > 8000) problem = \"desktop density must be between 250 and 8000 thousandths\";"
      , "  else {"
      , "    for (size_t i = 0; i < 4; ++i)"
      , "      if (limits[i] < 0) problem = \"desktop size limits cannot be negative\";"
      , "    if (problem == NULL)"
      , "      for (size_t i = 0; i < 4; ++i)"
      , "        if (limits[i] > 1000000) problem = \"desktop size limits exceed the platform limit\";"
      , "    if (problem == NULL && ((max_width_value > 0 && min_width_value > max_width_value) ||"
      , "        (max_height_value > 0 && min_height_value > max_height_value))) problem = \"desktop minimum size exceeds its maximum\";"
      , "    if (problem == NULL && (aspect_width_value < 0 || aspect_height_value < 0 ||"
      , "        aspect_width_value > 1000000 || aspect_height_value > 1000000)) problem = \"desktop aspect ratio must be positive\";"
      , "    if (problem == NULL && ((aspect_width_value == 0) != (aspect_height_value == 0)))"
      , "      problem = \"desktop aspect ratio needs both terms\";"
      , "  }"
      , "  if (problem != NULL) { pudu_host_fail(problem); return 0; }"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  return pudu_desktop_problem(\"configure\", pudu_desktop_configure((*window)->handle,"
      , "    (int32_t)density_value, (int32_t)min_width_value, (int32_t)min_height_value, (int32_t)max_width_value, (int32_t)max_height_value, (int32_t)aspect_width_value, (int32_t)aspect_height_value, fullscreen));"
      , "#else"
      , "  (void)token; (void)fullscreen;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_clipboard_write", ["host_desktop"],
      [ "static int pudu_host_desktop_clipboard_write(pudu_text value) {"
      , "#if defined(__APPLE__)"
      , "  return pudu_desktop_problem(\"clipboard\", pudu_desktop_clipboard_write(value.bytes, value.length));"
      , "#else"
      , "  (void)value;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_accessibility", ["host_desktop"],
      [ "static int pudu_host_desktop_accessibility(pudu_int token, pudu_text records) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  int status = pudu_desktop_accessibility((*window)->handle, records.bytes, records.length);"
      , "  if (status == -3) { pudu_host_fail(\"desktop accessibility snapshot is malformed\"); return 0; }"
      , "  return pudu_desktop_problem(\"accessibility snapshot\", status);"
      , "#else"
      , "  (void)token; (void)records;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_menu", ["host_desktop"],
      [ "static int pudu_host_desktop_menu(pudu_int token, pudu_text records) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return 0;"
      , "  int status = pudu_desktop_menu((*window)->handle, records.bytes, records.length);"
      , "  if (status == -3) { pudu_host_fail(\"desktop menu bar is malformed\"); return 0; }"
      , "  return pudu_desktop_problem(\"menu bar\", status);"
      , "#else"
      , "  (void)token; (void)records;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return 0;"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_inputs", ["host_desktop", "text_copy"],
      [ "static pudu_text pudu_host_desktop_inputs(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return (pudu_text){0};"
      , "  int64_t held = pudu_desktop_inputs((*window)->handle, NULL, 0);"
      , "  if (held < 0) { pudu_desktop_problem(\"input\", (int)held); return (pudu_text){0}; }"
      , "  if (held == 0) { pudu_host_done(0); return pudu_text_copy(\"\", 0); }"
      , "  size_t capacity = (size_t)held;"
      , "  unsigned char *buffer = malloc(capacity);"
      , "  if (buffer == NULL) pudu_memory_failure();"
      , "  int64_t copied = pudu_desktop_inputs((*window)->handle, buffer, capacity);"
      , "  if (copied != held) {"
      , "    free(buffer);"
      , "    pudu_host_done(0);"
      , "    return pudu_text_copy(\"\", 0);"
      , "  }"
      , "  pudu_text answer = pudu_text_copy((const char *)buffer, (size_t)copied);"
      , "  free(buffer);"
      , "  pudu_host_done(0);"
      , "  return answer;"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return (pudu_text){0};"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_clipboard_read", ["host_desktop", "text_copy"],
      [ "static pudu_text pudu_host_desktop_clipboard_read(void) {"
      , "#if defined(__APPLE__)"
      , "  int64_t held = pudu_desktop_clipboard_read(NULL, 0);"
      , "  if (held == -5) { pudu_host_fail(\"the clipboard holds no text\"); return (pudu_text){0}; }"
      , "  if (held < 0) { pudu_desktop_problem(\"clipboard\", (int)held); return (pudu_text){0}; }"
      , "  size_t capacity = held == 0 ? 1 : (size_t)held;"
      , "  unsigned char *buffer = malloc(capacity);"
      , "  if (buffer == NULL) pudu_memory_failure();"
      , "  int64_t copied = pudu_desktop_clipboard_read(buffer, capacity);"
      , "  if (copied != held) {"
      , "    free(buffer);"
      , "    pudu_host_fail(\"the clipboard changed while it was read\");"
      , "    return (pudu_text){0};"
      , "  }"
      , "  pudu_text answer = pudu_text_copy((const char *)buffer, (size_t)copied);"
      , "  free(buffer);"
      , "  pudu_host_done(0);"
      , "  return answer;"
      , "#else"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return (pudu_text){0};"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_accessibility_report", ["host_desktop", "text_copy"],
      [ "static pudu_text pudu_host_desktop_accessibility_report(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
      , "  if (*window == NULL) return (pudu_text){0};"
      , "  int64_t held = pudu_desktop_accessibility_report((*window)->handle, NULL, 0);"
      , "  if (held < 0) { pudu_desktop_problem(\"accessibility tree\", (int)held); return (pudu_text){0}; }"
      , "  size_t capacity = held == 0 ? 1 : (size_t)held;"
