      , "  if (buffer == NULL) pudu_memory_failure();"
      , "  int64_t copied = pudu_desktop_accessibility_report((*window)->handle, buffer, capacity);"
      , "  if (copied != held) {"
      , "    free(buffer);"
      , "    pudu_host_fail(\"the accessibility tree changed while it was read\");"
      , "    return (pudu_text){0};"
      , "  }"
      , "  pudu_text answer = pudu_text_copy((const char *)buffer, (size_t)copied);"
      , "  free(buffer);"
      , "  pudu_host_done(0);"
      , "  return answer;"
      , "#else"
      , "  (void)token;"
      , "  pudu_host_fail(\"desktop presentation is unsupported on this platform\");"
      , "  return (pudu_text){0};"
      , "#endif"
      , "}"
      ])
  , ("host_desktop_menu_report", ["host_desktop", "text_copy"],
      [ "static pudu_text pudu_host_desktop_menu_report(pudu_int token) {"
      , "#if defined(__APPLE__)"
      , "  pudu_window **window = pudu_window_find(token);"
